def fixture():
    raw = FIXTURE.encode("utf-8")
    if hashlib.sha256(raw).hexdigest() != FIXTURE_SHA256:
        raise AssertionError("legacy synthetic fixture hash mismatch")
    return json.loads(raw)


class LegacyCompletedOperatorTests(unittest.TestCase):
    def test_original_production_completed_job_recovers_without_mutations_or_calls(
        self,
    ):
        saved = fixture()
        self.assertEqual(
            saved["baseline_zip_sha256"],
            "2a523efcc64df8cf5750ff2721f3a5bfd7658b7c1ba898ca9bee0e53185b4406",
        )
        original = {
            name: content.encode("utf-8")
            for name, content in saved["artifacts"].items()
        }
        for phase, version in (
            ("generate", "rule-surge-runtime-independent-generation-v4"),
            ("review", "rule-surge-runtime-review-v5"),
        ):
            request = json.loads(original[phase + "/request.json"])
            self.assertEqual(request["prompt_version"], version)
            self.assertNotIn("operator_contract_version", request["context"])
            self.assertIn(
                "operator为equal、contain或notcontain",
                request["messages"][0]["content"],
            )
        expected = json.loads(original["result.json"])
        forbidden = Mock(
            side_effect=AssertionError(
                "frozen replay must not invoke external dependencies"
            )
        )
        with tempfile.TemporaryDirectory() as directory:
            folder = Path(directory) / "jobs" / saved["job_id"]
            folder.mkdir(parents=True)
            for name, content in original.items():
                path = folder / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
            engine = processor.SurgeProcessor(
                directory,
                load_case=forbidden,
                load_rules=forbidden,
                generate=forbidden,
                model=saved["model"],
                budget=Budget(),
            )
            result = engine.process(saved["signal"])
            self.assertEqual(result["status"], "received")
            self.assertEqual(result["record_id"], expected["record_id"])
            self.assertEqual(result["model_calls_this_attempt"], 0)
            self.assertTrue(result["analysis_reused"])
            self.assertTrue(engine.verify_durable_result(saved["signal"], result))
            self.assertEqual(
                original,
                {
                    p.relative_to(folder).as_posix(): p.read_bytes()
                    for p in folder.rglob("*")
                    if p.is_file()
                },
            )
            forbidden.assert_not_called()

    def test_actual_legacy_draft_can_be_projected_into_new_review_without_rewriting(
        self,
    ):
        saved = fixture()
        unchanged = copy.deepcopy(saved)
        source = json.loads(saved["artifacts"]["generate/parsed.json"])["reply"]
        previous = json.loads(saved["artifacts"]["review/request.json"])
        case = json.loads(saved["artifacts"]["case.json"])
        context = previous["context"]
        projected = ai.build_request(
            case["rule"],
            context["current_samples"],
            context["history_samples"],
            context["coverage"],
            draft=source,
            phase="review",
            limits=Budget(),
        )
        self.assertEqual(projected["prompt_version"], ai.PROMPT_VERSION)
        self.assertEqual(
            projected["context"]["draft"]["filter"]["A"]["operator"], "Contains"
        )
        self.assertEqual(
            projected["context"]["draft_operator_projection"]["source_filter_sha256"],
            hashlib.sha256(ai.encoded(source["filter"])).hexdigest(),
        )
        self.assertEqual(
            projected["context"]["current_samples"], context["current_samples"]
        )
        self.assertEqual(
            projected["context"]["history_samples"], context["history_samples"]
        )
        self.assertEqual(saved, unchanged)
        self.assertEqual(source["filter"]["A"]["operator"], "contain")


if __name__ == "__main__":
    unittest.main()
